/**
 * The A1 oracle fixtures are generated by `apps/crq-python/fixtures/a1-status/
 * emit.py` from the real Python modules. This named test runs the generator's
 * `--check` mode so a stale fixture fails in the focused suite instead of
 * silently becoming the expected bytes.
 *
 * It is a process test by necessity: it invokes the production Python minor,
 * not a JavaScript reimplementation of the oracle.
 */
import { spawnSync } from 'node:child_process';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { expect, test } from 'vitest';

const CRQ = resolve(dirname(fileURLToPath(import.meta.url)), '../../../apps/crq-python');

test('a1-status fixtures are current with the Python oracle', () => {
  const result = spawnSync('python3', ['fixtures/a1-status/emit.py', '--check'], {
    cwd: CRQ,
    encoding: 'utf8',
  });
  expect(result.error).toBeUndefined();
  expect(result.stderr, result.stdout).toBe('');
  expect(result.status, result.stdout).toBe(0);
});
